from .data.Event import Event
from .data.Fault import Fault
import re
from copy import deepcopy
from ..exceptions import HeaderParsingError
from ...pylogger.logger import log_operation, log_result, log_suppression


class FaultHistory:

    """ Parser for Fault History Log """

    def __init__(self, log):
        self._raw_log = log
        self._log = deepcopy(log)
        self._log_timestamp = None
        self._active_faults = None
        self._inactive_faults = None
        self._fault_events = None
        self.__active_faults_index = None
        self.__inactive_faults_index = None
        self.__fault_events_index = None

    def parse(self):
        """
        Parses fault_history_log.txt read via command terminal on radio unit.

        :return: Dictionary with information about active, inactive faults and faults events.
        :rtype:  dict
        """
        self._split_log_per_line()
        self._clear_log_from_whitespaces()
        self._clear_log_from_faults_headers()

        self._set_log_timestamp()
        self._set_active_faults()
        self._set_inactive_faults()
        self._set_fault_events()

        return {
            "Active Faults": self.__build_faults_list(self._active_faults),
            "Inactive Faults": self.__build_faults_list(self._inactive_faults),
            "Fault Events": self.__build_events_list(self._fault_events)
        }

    def _set_active_faults(self):
        """
        Sets active faults by reading proper parsed lines from log as List of Fault class instance from .data.Fault
        under `_active_faults` attribute.

        :raises HeaderParsingError exception when `Active faults` or `InActive faults` header could not be found
                in parsed lines from log.
        :raises DegeneratedEntry exception when any of read entries from parsed log lines contains incomplete entry
                data.
        """
        if not self.__active_faults_index:
            self.__set_active_faults_index()

        if not self.__inactive_faults_index:
            self.__set_inactive_faults_index()

        self._active_faults = [Fault(entry=entry) for entry in
                               self._log[self.__active_faults_index + 1:self.__inactive_faults_index]]

    def _set_inactive_faults(self):
        """
        Sets inactive faults by reading proper parsed lines from log as List of Fault class instance from .data.Fault
        under `_inactive_faults` attribute.

        :raises HeaderParsingError exception when `InActive faults` or `Fault events` header could not be found
                in parsed lines from log.
        :raises DegeneratedEntry exception when any of read entries from parsed log lines contains incomplete entry
                data.
        """
        if not self.__inactive_faults_index:
            self.__set_inactive_faults_index()

        if not self.__fault_events_index:
            self.__set_fault_events_index()

        self._inactive_faults = [Fault(entry=entry) for entry in
                                 self._log[self.__inactive_faults_index + 1:self.__fault_events_index]]

    def _set_fault_events(self):
        """
        Sets fault events by reading proper parsed lines from log as List of Event class instance from .data.Event
         under `_fault_events` attribute.

        :raises HeaderParsingError exception `Fault events` header could not be found in parsed lines from log.
        :raises DegeneratedEntry exception when any of read entries from parsed log lines contains incomplete entry
                data.
        """
        if not self.__fault_events_index:
            self.__set_fault_events_index()

        self._fault_events = [Event(entry=entry) for entry in self._log[self.__fault_events_index + 1:]]

    def _set_log_timestamp(self):
        """
        Sets log timestamp read from log file. If timestamp won't be available then parser will ignore
        error and go further as log timestamp is not that important information.
        """
        pattern = r'[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}.[0-9]{6}Z'

        log_operation("Setting log timestamp of log report.")
        if not self._log_timestamp:
            try:
                self._log_timestamp = re.findall(pattern, self._log[0])[0]
            except IndexError:
                log_suppression("No correct timestamp available in log file, please check "
                                "if log is not corrupted!")

            if not self._log_timestamp:
                log_suppression("Could not parse fault history log timestamp (read value: {0})".
                                format(self._log_timestamp))

        log_result("Log timestamp has been set.")

    def _split_log_per_line(self):
        """ Splits whole str log file into list of string to prepare log for faults parsing. """
        log_operation("Splitting str log file into str lines.")
        self._log = self._log.split("\n")
        log_result("Splitting performed successfully.")

    def _clear_log_from_whitespaces(self):
        """ Clears log (list of strings) of unnecessary elements containing only whitespaces. """
        log_operation("Clearing log from unnecessary whitespaces.")
        self._log = filter(lambda log_line: log_line.strip(), self._log)

        if not isinstance(self._log, list):
            self._log = list(self._log)

        log_result("Removal performed successfully.")

    def _clear_log_from_faults_headers(self):
        """
        Clears log from headline and columns names of type of fault or event.
        There are three types of headers:
        1. Active Faults with header and column names in manner:

        [TimeStamp], [Id], [Source], [Severity], [NumOfFaults] (current/last 10s 1min 1h day all)
        =========================================================================================

        2. InActive Faults with header and column names as above;

        3. Fault Events with header and column names in manner:

        [TimeStamp], [Id], [Source], [Severity], [State]
        ================================================================================

        Method clears unnecessary headers as above.

        """
        for line in self._log:

            if line.startswith(" Active faults:"):
                self.__clear_log_from_active_faults_header(line)

            if line.startswith(" InActive faults:"):
                self.__clear_log_from_inactive_faults_header(line)

            if line.startswith(" Fault events:"):
                self.__clear_log_from_fault_events_header(line)

    def __set_active_faults_index(self):
        """
        Finds index of list' element that contains `Active faults` header.

        :raises HeaderParsingError exception when `Active faults` header could not be found
                in parsed lines from log.
        """
        log_operation("Setting active faults index...")
        for line in self._log:
            if " Active faults:" in line:
                self.__active_faults_index = self._log.index(line)

        if not self.__active_faults_index:
            raise HeaderParsingError("Could not find \'Active faults\' header in fault_history_log.txt")

        log_result("Active faults index has been set")

    def __set_inactive_faults_index(self):
        """
        Finds index of list' element that contains `InActive faults` header.

        :raises HeaderParsingError exception when `InActive faults` header could not be found
                in parsed lines from log.
        """
        log_operation("Setting inactive faults index...")
        for line in self._log:
            if " InActive faults:" in line:
                self.__inactive_faults_index = self._log.index(line)

        if not self.__inactive_faults_index:
            raise HeaderParsingError("Could not find \'InActive faults\' header in fault_history_log.txt")

        log_result("Active faults index has been set")

    def __set_fault_events_index(self):
        """
        Finds index of list' element that contains `Fault events` header.

        :raises HeaderParsingError exception when `Fault events` header could not be found
                in parsed lines from log.
        """
        log_operation("Setting fault events index...")
        for line in self._log:
            if 'Fault events' in line:
                self.__fault_events_index = self._log.index(line)

        if not self.__fault_events_index:
            raise HeaderParsingError("Could not find \'Fault events\' header in fault_history_log.txt")

        log_result("Fault events index has been set")

    def __clear_log_from_active_faults_header(self, line):
        log_operation("Clearing log from `Active faults` header and caption...")
        faults_index = self._log.index(line)
        del self._log[faults_index + 1:faults_index + 3]
        log_result("`Active faults` header cleared successfully.")

    def __clear_log_from_inactive_faults_header(self, line):
        log_operation("Clearing log from `Inactive faults` header and caption...")
        faults_index = self._log.index(line)
        del self._log[faults_index + 1:faults_index + 3]
        log_result("`Inactive faults` header cleared successfully.")

    def __clear_log_from_fault_events_header(self, line):
        log_operation("Clearing log from `Fault events` header and caption...")
        faults_index = self._log.index(line)
        del self._log[faults_index + 1:faults_index + 3]
        log_result("`Fault events` header cleared successfully.")

    @staticmethod
    def __build_faults_list(faults):
        faults_list = []

        for fault in faults:
            faults_list.append(
                {
                    'id': fault.id,
                    'severity': fault.severity,
                    'source': fault.source,
                    'num_of_faults': fault.num_of_faults,
                    'timestamp': fault.timestamp
                }
            )

        return faults_list

    @staticmethod
    def __build_events_list(events):
        events_list = []

        for event in events:
            events_list.append(
                {
                    'id': event.id,
                    'severity': event.severity,
                    'source': event.source,
                    'state': event.state,
                    'timestamp': event.timestamp
                }
            )

        return events_list
